  for (let n = n0; n <= limite; n++) {
    if (a * n + b < c * n) {
      return false;
    }
  }
  return true;
}

function esAjustadaLineal(a, b, c1, c2, n0, limite) {
  return cotaInferiorLineal(a, b, c1, n0, limite) && cotaSuperiorLineal(a, b, c2, n0, limite);
